SET NAMES utf8mb4;

-- Restore editable, unapproved drafts for title-only fallback records.
-- These are broad position-level drafts, not copies of any role-specific description.
-- Fill only blank fields on active records still awaiting HR review. Preserve all edits,
-- approvals, qualifications, reporting lines, role-specific records and employee data.
UPDATE hr_job_description_templates
SET
    role_purpose = CASE
        WHEN NULLIF(TRIM(role_purpose), '') IS NOT NULL THEN role_purpose
        WHEN position_title = 'المدير العام' THEN 'قيادة الجمعية ومتابعة تحقيق أهدافها واتخاذ القرارات الإدارية والتنظيمية ضمن الصلاحيات المعتمدة.'
        WHEN position_title = 'نائب المدير العام' THEN 'مساندة المدير العام في متابعة العمل المؤسسي وتنسيق المهام المفوضة ضمن حدود التفويض المعتمد.'
        WHEN position_title = 'المدير المالي' THEN 'ضمان سلامة المتابعة المالية والمحاسبية والرقابة والتسويات والإقفال المالي وفق الصلاحيات والإجراءات المعتمدة.'
        WHEN position_title = 'مدير الموارد البشرية' THEN 'تنظيم ومتابعة شؤون الموظفين وسجلاتهم وإجراءات التوظيف والعقود والحضور والإجازات والرواتب بالتنسيق مع الجهات المخولة.'
        WHEN position_title = 'مدير النظام' THEN 'المحافظة على جاهزية النظام وسلامة حسابات المستخدمين وبياناتهم وإعداداتهم ضمن التفويض وضوابط أمن المعلومات.'
        WHEN position_title = 'مشرف' THEN 'متابعة الأعمال التشغيلية والكفلاء أو السجلات الواقعة ضمن نطاق الإشراف المسند وتوثيق نتائج المتابعة.'
        WHEN position_title = 'مشرف مشروع' THEN 'تنسيق ومتابعة تنفيذ المشروع المسند وتوثيق التقدم والأنشطة والأدلة التشغيلية ورفع العوائق.'
        WHEN position_title = 'مندوب استرجاع الكفلاء' THEN 'متابعة حالات الكفلاء غير النشطين وتوثيق التواصل والنتائج ودعم استكمال إجراءات المتابعة المعتمدة.'
        WHEN position_title = 'محاسب' THEN 'تنفيذ المعاملات والأعمال المحاسبية المسندة وتوثيق مستنداتها ودعم المطابقات والتقارير وفق الصلاحيات.'
        WHEN position_title = 'موظف العلاقات العامة والإعلام' THEN 'دعم أنشطة العلاقات العامة والتواصل المؤسسي وإعداد المواد الإعلامية وفق التكليف والموافقات المعتمدة.'
        WHEN position_title = 'أخصائية شؤون الأمهات' THEN 'دعم متابعة شؤون الأمهات والملفات والخدمات والإحالات المرتبطة بالبرنامج ضمن نطاق العمل الفعلي، مع مراعاة السرية والحماية.'
        WHEN position_title = 'موظف' THEN 'إنجاز الأعمال التشغيلية المسندة من القسم والمشرف المباشر والمساهمة في تقديم خدمة موثوقة وفق الإجراءات والصلاحيات المحددة.'
        ELSE role_purpose
    END,
    responsibilities = CASE
        WHEN NULLIF(TRIM(responsibilities), '') IS NOT NULL THEN responsibilities
        WHEN position_title = 'المدير العام' THEN '• متابعة أهداف الجمعية وخططها وأدائها العام واتخاذ القرارات الداخلة ضمن الصلاحيات.\n• مراجعة المعاملات المحالة إلى الإدارة العليا وتوثيق قراراتها ونتائجها.\n• متابعة تنفيذ القرارات والتنسيق بين الوحدات الإدارية.\n• احترام فصل الصلاحيات وعدم الحلول محل الجهة المالية في الترحيل أو التسوية.'
        WHEN position_title = 'نائب المدير العام' THEN '• متابعة تنفيذ المهام والقرارات المفوضة من المدير العام.\n• تنسيق الأعمال بين الوحدات عند التكليف ومتابعة ما يتطلب استكمالاً.\n• تنفيذ إسناد المشرفين أو إعادة الإسناد فقط عبر المسارات والصلاحيات المخولة.\n• رفع المسائل التي تتجاوز التفويض إلى المدير العام.'
        WHEN position_title = 'المدير المالي' THEN '• مراجعة المعاملات المالية والمحاسبية والأدلة المؤيدة ضمن الصلاحيات.\n• متابعة الخزينة والمطابقات والتسويات والتقارير والأرصدة.\n• مراجعة الإقفال المالي للمشروعات والتحقق من المستندات والرصيد المتبقي.\n• متابعة صحة التوثيق والفصل بين الطلب التشغيلي والمراجعة والاعتماد والترحيل.'
        WHEN position_title = 'مدير الموارد البشرية' THEN '• إدارة وتحديث سجلات الموظفين وبيانات التوظيف والارتباط الوظيفي والعقود.\n• متابعة الحضور وطلبات الإجازات وسجلات الرواتب وفق الإجراءات والسياسات المعتمدة.\n• مراجعة بيانات الموارد البشرية والتأكد من توثيق الإجراءات والقرارات.\n• التنسيق مع المالية في شؤون الرواتب دون تجاوز صلاحياتها المحاسبية.'
        WHEN position_title = 'مدير النظام' THEN '• إدارة حسابات المستخدمين والأدوار والصلاحيات والإعدادات التقنية ضمن التفويض.\n• متابعة المشكلات التقنية ودعم استمرارية النظام وسلامة البيانات.\n• توثيق التغييرات التقنية المصرح بها وحماية سرية المعلومات.\n• عدم استخدام الصلاحيات التقنية لتجاوز اعتماد أو إجراء تشغيلي محجوز لدور آخر.'
        WHEN position_title = 'مشرف' THEN '• متابعة الكفلاء أو السجلات والطلبات الواقعة ضمن النطاق المسند للحساب.\n• تحديث المعلومات التشغيلية المسموح بها وتوثيق المتابعات والنتائج.\n• تقديم الطلبات التشغيلية المطلوبة وإرفاق الأدلة المتاحة عند الحاجة.\n• إحالة المسائل المالية أو قرارات إعادة الإسناد إلى الجهة المخولة.'
        WHEN position_title = 'مشرف مشروع' THEN '• متابعة الأنشطة والمخرجات والجدول التشغيلي للمشروع المسند.\n• تحديث بيانات التقدم وتوثيق المصروفات أو الأدلة التشغيلية المسموح بها بحسب الصلاحيات.\n• تسجيل العوائق والمخاطر ورفعها إلى مدير المشروع أو المسؤول المختص.\n• إحالة المطابقة والإقفال المالي إلى الإدارة المالية وعدم اعتمادها من جانب واحد.'
        WHEN position_title = 'مندوب استرجاع الكفلاء' THEN '• مراجعة حالات الكفلاء غير النشطين المتاحة للمتابعة والتواصل وفق الإجراءات المعتمدة.\n• تسجيل محاولات التواصل والردود والنتائج بدقة في النظام.\n• متابعة الخطوات التشغيلية المسموح بها ورفع الحالات التي تحتاج إلى تدخل.\n• حماية بيانات الكفلاء وعدم تقديم وعود أو التزامات غير مصرح بها.'
        WHEN position_title = 'محاسب' THEN '• معالجة المعاملات المحاسبية المسندة استناداً إلى المستندات المؤيدة.\n• إدخال أو مراجعة البيانات والقيود المتاحة ضمن الصلاحيات والتحقق من اكتمال الأدلة.\n• دعم المطابقات والتسويات وإعداد التقارير المالية المطلوبة.\n• حفظ السجلات وإحالة الاستثناءات وقرارات الاعتماد المحجوزة إلى المدير المالي.'
        WHEN position_title = 'موظف العلاقات العامة والإعلام' THEN '• إعداد أو تنسيق المواد والرسائل الإعلامية التي تم اعتمادها للنشر.\n• دعم أنشطة التواصل والعلاقات العامة وتوثيق الأعمال المنفذة وفق التكليف.\n• التحقق من الموافقات قبل نشر معلومات الجمعية أو صور وبيانات المستفيدين.\n• الالتزام بالهوية المؤسسية والسرية وسياسات الحماية.'
        WHEN position_title = 'أخصائية شؤون الأمهات' THEN '• متابعة الملفات والمعلومات التشغيلية المتعلقة بشؤون الأمهات ضمن نطاق البرنامج والتكليف.\n• تنسيق التواصل والخدمات أو الإحالات ذات الصلة وتوثيق المتابعة في السجلات المسموح بها.\n• المحافظة على سرية المعلومات واحترام كرامة المستفيدات.\n• اتباع إجراءات الحماية ورفع أي مخاوف إلى المسؤول المختص. يجب أن يؤكد HR والمشرف المباشر التفاصيل الفعلية قبل الاعتماد.'
        WHEN position_title = 'موظف' THEN '• إنجاز الطلبات والمهام التشغيلية التي يحددها القسم والمشرف المباشر ضمن صلاحيات الحساب.\n• تحديث السجلات أو النماذج المتاحة بدقة وحفظ المستندات والأدلة المطلوبة.\n• الالتزام بإجراءات الجمعية والسرية والحماية والسلامة ذات الصلة.\n• توثيق النتائج وإحالة المهام أو القرارات التي تتطلب دوراً آخر إلى المسؤول المخول؛ يجب تخصيص البنود حسب عمل الموظف الفعلي قبل الاعتماد.'
        ELSE responsibilities
    END,
    updated_at = CURRENT_TIMESTAMP
WHERE TRIM(COALESCE(system_role_code, '')) = ''
  AND description_status = 'needs_review'
  AND is_active = 1
  AND position_title <> 'HR Test'
  AND (
      NULLIF(TRIM(role_purpose), '') IS NULL
      OR NULLIF(TRIM(responsibilities), '') IS NULL
  );
